/* Risdel Books Module 30 — Administration, System Configuration & Audit Centre
   Future SQL Server migration reference. Google Sheets remains the active provider. */
IF OBJECT_ID('dbo.System_FeatureFlags') IS NULL CREATE TABLE dbo.System_FeatureFlags(Id uniqueidentifier NOT NULL PRIMARY KEY,FeatureKey nvarchar(100) NOT NULL UNIQUE,Name nvarchar(200) NOT NULL,Module nvarchar(100) NULL,Description nvarchar(1000) NULL,IsEnabled bit NOT NULL DEFAULT 1,UpdatedAt datetime2 NULL,UpdatedBy nvarchar(100) NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.System_Integrations') IS NULL CREATE TABLE dbo.System_Integrations(Id uniqueidentifier NOT NULL PRIMARY KEY,IntegrationKey nvarchar(100) NOT NULL UNIQUE,Name nvarchar(200) NOT NULL,IntegrationType nvarchar(100) NULL,Provider nvarchar(200) NULL,Status nvarchar(50) NULL,ConfigurationReference nvarchar(500) NULL,LastCheckedAt datetime2 NULL,Notes nvarchar(max) NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.System_BackupRuns') IS NULL CREATE TABLE dbo.System_BackupRuns(Id uniqueidentifier NOT NULL PRIMARY KEY,BackupNumber nvarchar(50) NOT NULL UNIQUE,BackupType nvarchar(100) NOT NULL,Status nvarchar(50) NOT NULL,StorageReference nvarchar(1000) NULL,StartedAt datetime2 NULL,CompletedAt datetime2 NULL,RequestedBy nvarchar(100) NULL,Notes nvarchar(max) NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.System_HealthChecks') IS NULL CREATE TABLE dbo.System_HealthChecks(Id uniqueidentifier NOT NULL PRIMARY KEY,CheckKey nvarchar(100) NOT NULL,Name nvarchar(200) NOT NULL,Status nvarchar(50) NOT NULL,Message nvarchar(1000) NULL,CheckedAt datetime2 NOT NULL,CheckedBy nvarchar(100) NULL,IsActive bit NOT NULL DEFAULT 1);
IF OBJECT_ID('dbo.System_AdminEvents') IS NULL CREATE TABLE dbo.System_AdminEvents(Id uniqueidentifier NOT NULL PRIMARY KEY,EventType nvarchar(100) NOT NULL,EntityType nvarchar(100) NULL,EntityId nvarchar(100) NULL,Description nvarchar(1000) NULL,OccurredAt datetime2 NOT NULL,OccurredBy nvarchar(100) NULL,IsActive bit NOT NULL DEFAULT 1);
